types.ArchiveResult:
public class ArchiveResult
{
    /* What the caller gets back: where the archive came from and how to fetch it. */

    /* The folder that was packed, exactly as it was asked for. */
    public string folder { get; set; }

    /* A link the platform issues for the archive. It carries its own
       authorisation, so it works without the caller's session. */
    public string url { get; set; }
}

steps.expression:
// A store reaches the code only through its binding on the
// diagram; GetFolder turns that binding into the folder.
var folder = DataAssociations.DS_Folder.GetFolder();
if (!folder.IsExists())
    folder.CreateFolder();

Logger.LogInformation($"folder ready: {folder.FolderPath}");
return Input;

// AddToZip answers with the archive as a file of its own.
LocalFile archive = DataAssociations.DS_File.GetFile().AddToZip("archive.zip");

// The link carries its own authorisation: whoever receives it
// needs no session of yours to fetch the archive.
return new ArchiveResult() { folder = "flow-patterns/archive-demo", url = archive.CreateLink() };
